import React from "react";
import ReactSpeedometer from "react-d3-speedometer";

function RiskMeter({ score = 0 }) {
  // Ensure score is a valid number
  const parsedScore = typeof score === "number" ? score : parseFloat(score) || 0;

  return (
    <div className="speedometer-wrapper">
      <ReactSpeedometer
        fluidWidth={true}
        minValue={0}
        maxValue={100}
        value={parsedScore}
        segments={3}
        segmentColors={[
          "#10b981", // Low Risk: Emerald
          "#f59e0b", // Moderate Risk: Amber
          "#ef4444", // High Risk: Rose
        ]}
        needleColor="#f8fafc"
        needleTransition="easeElastic"
        needleTransitionDuration={1200}
        currentValueText="Product Risk Index: ${value}%"
        textColor="#94a3b8"
        ringWidth={30}
      />
    </div>
  );
}

export default RiskMeter;
